window.AUTH=window.AUTH||{};window.AUTH["20-382"]={"d":"20-382","id":"2020/20-382","n":"Guam v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Government of Guam","date":"2021-02-22","url":"https://www.supremecourt.gov/DocketPDF/20/20-382/169495/20210222105219570_2021-02-22%20Guam%20Merits%20Br%20w%20addendum.pdf","side":"pet","n":99},{"k":"respondent","label":"Brief of respondent United States","date":"2021-03-24","url":"https://www.supremecourt.gov/DocketPDF/20/20-382/172881/20210324162820256_20-382bsUnitedStates.pdf","side":"res","n":115},{"k":"reply","label":"Reply of petitioner Government of Guam","date":"2021-04-16","url":"https://www.supremecourt.gov/DocketPDF/20/20-382/175933/20210416130510101_2021-04-16%20No.%2020-382%20Guam%20reply%20brief.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r37_1an2.pdf","tr":true,"items":[{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"137 S. Ct. 1652","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Asarco LLC v. Atlantic Richfield Co.","cite":"866 F.3d 1108","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/866/1108/","by":{"0":"38","1":"23, 33, 35, 45","2":"15"}},{"t":"case","label":"Atlantic Richfield Co. v. Christian","cite":"140 S. Ct. 1335","y":2020,"id":"2019/17-1498","sc":1,"sum":"The Court held that the landowners in this case were potentially responsible parties under the Comprehensive Environmental Response, Compensation, and Liability Act (CERCLA) and thus need the Environmental Protection Agency’s approval to take remedial action.","sumSrc":"Oyez","by":{"0":"3, 4, 28, 39","1":"22, 31","2":"7, 20"}},{"t":"case","label":"Bernstein v. Bankert","cite":"733 F.3d 190","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/733/190/","by":{"0":"39, 40"}},{"t":"case","label":"Burdon Central Sugar Refining Co. v. Payne","cite":"167 U.S. 127","y":1897,"id":"scdb/1896-191","sc":1,"sum":"P. and P., owners of three sugar plantations in Louisiana, leased the sugar-house on one of them with all its machinery, and such defined land in that plantation as might be found necessary for its use, to F. and F. for a term of years. The lessees agreed to buy during the term, and the lessors agreed to sell and deliver to them during that time, the sugar-cane grown on the three plantations. Elaborate provisions …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Burlington Northern & Santa Fe Railway Co. v. United States","cite":"556 U.S. 599","y":2009,"id":"2008/07-1601","sc":1,"op":1,"sum":"The Court found that the defendants were not liable as the \"arranger\" for the contamination at issue, and therefore the liability calculations of the district court were appropriate.","sumSrc":"Oyez","by":{"0":"4, 22"}},{"t":"case","label":"Carr v. United States","cite":"560 U.S. 438","y":2010,"id":"2009/08-1301","sc":1,"sum":"The Court held that the Sex Offender and Registration Act does not apply to sex offenders' interstate travel that occurred before the Act's effective date.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Chemical Waste Management, Inc. v. EPA","cite":"869 F.2d 1526","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/869/1526/","by":{"0":"37"}},{"t":"case","label":"Chevron Mining Inc. v. United States","cite":"863 F.3d 1261","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/1261/","by":{"0":"23"}},{"t":"case","label":"City of Columbus v. Ours Garage & Wrecker Service, Inc.","cite":"536 U.S. 424","y":2002,"id":"2001/01-419","sc":1,"sum":"The Court held that section 14501(c) does not bar a State from delegating to municipalities and other local units the State's authority to establish safety regulations governing motor carriers of property, including tow trucks. \"A locality, as section 14501(c) recognizes, is a 'political subdivision' of the State,\" wrote Justice Ginsburg. \"Ordinarily, a political subdivision may exercise whatever portion of state power the State...chooses to delegate to the subdivision.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"City of Milwaukee v. Illinois","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"op":1,"sum":"Noting a “narrow exception” for admiralty cases.","sumSrc":"opinion","by":{"0":"25"}},{"t":"case","label":"Clay v. United States","cite":"537 U.S. 522","y":2003,"id":"2002/01-1500","sc":1,"sum":"The Court held that, for the purpose of starting the clock on section 2255's one-year limitation period, a judgment of conviction becomes final when the time expires for filing a petition for certiorari contesting the appellate court's affirmation of the conviction. Under this rule, Clay's section 2255 motion was timely filed.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Consolidated Edison Co. of New York, Inc. v. UGI Utilities, Inc.","cite":"423 F.3d 90","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/423/90/","by":{"0":"17, 25","1":"23"}},{"t":"case","label":"Cooper Industries, Inc. v. Aviall Services, Inc.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"op":2,"sum":"The Court held that a private party, who, like Aviall, had not been sued under CERCLA could not obtain cleanup contributions from other liable parties. The Court reasoned that CERCLA's language made clear that parties could seek cleanup contribution only during or following a civil action.","sumSrc":"Oyez","by":{"0":"5, 29","1":"3, 33"}},{"t":"case","label":"County Line Investment Co. v. Tinney","cite":"933 F.2d 1508","y":1991,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/933/1508/","by":{"0":"22, 23, 24","2":"6"}},{"t":"case","label":"County of Maui v. Hawaii Wildlife Fund","cite":"140 S. Ct. 1462","y":2020,"id":"2019/18-260","sc":1,"sum":"The Court held the Clean Water Act requires a permit when pollutants originate from a point source but are conveyed to navigable waters by a nonpoint source, such as groundwater, if the conveyance is the \"functional equivalent\" of a direct discharge.","sumSrc":"Oyez","by":{"0":"28","2":"12"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"0":"28","2":"12"}},{"t":"case","label":"Entergy Corp. v. Riverkeeper, Inc.","cite":"556 U.S. 208","y":2009,"id":"2008/07-588","sc":1,"op":1,"sum":"The Court found that the Environmental Protection Agency (EPA) was permitted to use a cost-benefit analysis while setting national performance standards for cooling water intake structures.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Exxon Corp. v. Hunt","cite":"475 U.S. 355","y":1986,"id":"1985/84-978","sc":1,"sum":"The New Jersey Spill Compensation and Control Act (Spill Act), enacted in 1977 to respond to the problem of hazardous substance release, imposes an excise tax upon major petroleum and chemical facilities within the State to finance the prevention and cleanup of oil spills and leaks of hazardous chemicals from disposal sites. The tax revenue goes into a permanent fund (Spill Fund), which may spend money not only to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"sum":"After respondent Mans filed for relief under Chapter 11 of the Bankruptcy Code, petitioners William and Norinne Field alleged, in effect, that letters Mans had written to them constituted fraudulent representations on which they relied in continuing to extend credit to a corporation controlled by Mans, and that, accordingly, Mans's obligation to them as guarantor of the corporation's debt should be excepted from …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34, 35, 36"}},{"t":"case","label":"Frew v. Hawkins","cite":"540 U.S. 431","y":2004,"id":"2003/02-628","sc":1,"sum":"The Court held that enforcement of the consent decree does not violate the 11th Amendment.","sumSrc":"Oyez","by":{"0":"30","1":"41","2":"10"}},{"t":"case","label":"Goodyear Atomic Corp. v. Miller","cite":"486 U.S. 174","y":1988,"id":"1987/86-1172","sc":1,"sum":"Appellee Miller, an employee of appellant at an Ohio nuclear production facility owned by the United States but operated by appellant, a private contractor, received a workers' compensation award from appellee Ohio Industrial Commission (Commission) for injuries sustained in a fall allegedly caused by a bolt protruding from the scaffold on which he was working. On the basis of a state safety regulation prohibiting …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Gutierrez v. Ada","cite":"528 U.S. 250","y":2000,"id":"1999/99-51","sc":1,"sum":"The Court held that \"[t]he Guam Organic Act does not require a runoff election when a candidate slate has received a majority of the votes cast for Governor and Lieutenant Governor of the Territory, but not a majority of the number of ballots cast in the simultaneous general election.\" Justice Souter wrote for the Court that an \"obvious reading\" of the law requires only a majority of votes cast in that one specific race, \"Congress did not shift its attention when it used 'any election' unadorned by a gubernatorial reference or other definite modifier.\".","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"op":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"32","1":"16"}},{"t":"case","label":"Kapral v. United States","cite":"166 F.3d 565","y":1999,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/166/565/","by":{"0":"33"}},{"t":"case","label":"Key Tronic Corp. v. United States","cite":"511 U.S. 809","y":1994,"id":"1993/93-376","sc":1,"sum":"CERCLA § 107 does not provide for the award of private litigants' attorney's fees associated with bringing a cost recovery action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 39"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Life Technologies Corp. v. Promega Corp.","cite":"137 S. Ct. 734","y":2017,"id":"2016/14-1538","sc":1,"sum":"The Court held that supplying a single component of a multi-component invention from the United States for sale abroad does not expose the manufacturer to liability for infringement based on worldwide sales.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Local No. 93, International Ass’n of Firefighters v. City of Cleveland","cite":"478 U.S. 501","y":1986,"id":"1985/84-1999","sc":1,"sum":"The Court held that section 706(g) of Title VII does not apply to relief awarded in a consent decree.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"M & G Polymers USA, LLC v. Tackett","cite":"574 U.S. 427","y":2015,"id":"2014/13-1010","sc":1,"sum":"The Court ruled that collective bargaining agreements should always be interpreted according to ordinary principles of contract law.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"op":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"33, 35"}},{"t":"case","label":"Meghrig v. KFC Western, Inc.","cite":"516 U.S. 479","y":1996,"id":"1995/95-83","sc":1,"sum":"In a unanimous opinion delivered by Justice Sandra Day O'Connor the Court held that section 6972 does not authorize a private cause of action to recover the prior cost of cleaning up toxic waste that does not, at the time of suit, continue to pose an endangerment to health or the environment.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Merit Management Group, LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"op":1,"sum":"The Court held that the safe harbor provision of 11 U.S.C. § 546(e), which prohibits a trustee from avoiding a transfer made by or to a financial institution, does not include transfers where the benefit and detriment of the transfer impact companies that are not financial institutions.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Mid-Con Freight Systems, Inc. v. Michigan Public Service Commission","cite":"545 U.S. 440","y":2005,"id":"2004/03-1234","sc":1,"sum":"The Court held that \"reference to text, historical context, and purpose\" proved that the words \"state registration requirement\" in the federal law applied only to state requirements concerning SSRS registration. The Michigan statute, the majority reasoned, had nothing to do with SSRS.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Middlesex County Sewerage Authority v. National Sea Clammers Ass’n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"op":1,"sum":"Respondents (an organization whose members harvest fish and shellfish off the coast of New York and New Jersey and one individual member) brought suit in Federal District Court against petitioners (various governmental entities and officials from New York, New Jersey, and the Federal Government), alleging damage to fishing grounds caused by discharges and ocean dumping of sewage and other waste. Invoking a number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","2":"11"}},{"t":"case","label":"Mitsui & Co. v. American Export Lines, Inc.","cite":"636 F.2d 807","y":1981,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/636/807/","by":{"0":"45"}},{"t":"case","label":"Morristown Associates v. Grant Oil Co.","cite":"106 A.3d 1176","y":2015,"court":"N.J.","url":"https://www.courtlistener.com/c/A.3d/106/1176/","by":{"0":"27"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"op":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19, 38"}},{"t":"case","label":"Ngiraingas v. Sanchez","cite":"495 U.S. 182","y":1990,"id":"1989/88-1281","sc":1,"sum":"Neither the Territory of Guam nor its officers acting in their official capacities are \"persons\" under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7"}},{"t":"case","label":"Niagara Mohawk Power Corp. v. Chevron U.S.A., Inc.","cite":"596 F.3d 112","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/596/112/","by":{"0":"23, 27, 28","1":"24"}},{"t":"case","label":"Norfolk Southern Railway Co. v. James N. Kirby, Pty. Ltd.","cite":"543 U.S. 14","y":2004,"id":"2004/02-1028","sc":1,"op":1,"sum":"The Court held that federal law controlled the interpretation of both bills, because they were maritime contracts and the dispute was not inherently local. The Court also held that the 11th Circuit misinterpreted the bills as not protecting Norfolk.","sumSrc":"Oyez","by":{"0":"45, 46"}},{"t":"case","label":"Northwest Airlines, Inc. v. Transport Workers Union of Am.","cite":"451 U.S. 77","y":1981,"id":"1980/79-1056","sc":1,"op":2,"sum":"Noting a “narrow exception” for admiralty cases.","sumSrc":"opinion","by":{"0":"21","1":"3, 4, 29","2":"9"}},{"t":"case","label":"Price Trucking Corp. v. Norampac Industries, Inc.","cite":"748 F.3d 75","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/748/75/","by":{"0":"17"}},{"t":"case","label":"Rogers v. Commissioner","cite":"908 F.3d 1094","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/908/1094/","by":{"0":"39"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"op":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","1":"17"}},{"t":"case","label":"S & E Contractors, Inc. v. United States","cite":"406 U.S. 1","y":1972,"id":"1971/70-88","sc":1,"sum":"In a contract disputes procedure, the Atomic Energy Commission (AEC) approved claims of its contractor for additional compensation. In response to an AEC certifying officer's request for advice as to one item, however, the General Accounting Office (GAO) ruled that the claims could not be certified for payment. When the AEC then refused to pay the compensation, the contractor brought suit in the Court of Claims …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"S.D. Warren Co. v. Maine Board of Environmental Protection","cite":"547 U.S. 370","y":2006,"id":"2005/04-1527","sc":1,"sum":"The Supreme Court held that the term \"discharge\" in section 401 had historically been given a broad meaning by FERC, the Environmental Protection Agency, and even the Supreme Court. Justice David Souter, in the Opinion of the Court, wrote that \"[w]hen it applies to water, 'discharge' commonly means a 'flowing or issuing out.' .","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Sturgeon v. Frost","cite":"136 S. Ct. 1061","y":2016,"id":"2015/14-1209","sc":1,"op":1,"sum":"The Court held that the Alaska National Interest Lands Conservation Act of 1980 did not allow the National Park Service to regulate all land physically within the boundaries of the National Park System in Alaska.","sumSrc":"Oyez","by":{"0":"24","2":"1"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20"}},{"t":"case","label":"Tarrant Regional Water District v. Herrmann","cite":"569 U.S. 614","y":2013,"id":"2012/11-889","sc":1,"sum":"The Court held that Congress’ approval of an interstate water compact does not violate the Commerce Clause and that the compact does respect state lines.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Texas & Pacific Railway Co. v. Clayton","cite":"173 U.S. 348","y":1899,"id":"scdb/1898-091","sc":1,"sum":"The Texas and Pacific Railway Company recéived at Bonham, in Texas, 467 bales of cotton for transportation to Liverpool. It was to be taken by the company over its road to New Orleans, and thence to Liverpool by a steamship company, to which it was to be delivered by the railway company at its wharf in New Orleans. Each bill of lading contained the following, among other clauses: “ The terms and conditions hereof …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Trinity Industries, Inc. v. Greenlease Holding Co.","cite":"903 F.3d 333","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/903/333/","by":{"0":"23"}},{"t":"case","label":"United States v. Armour & Co.","cite":"402 U.S. 673","y":1971,"id":"1970/759","sc":1,"sum":"The ownership of the majority of the stock of Armour & Co., a meatpacker, by Greyhound Corp., which has retail food subsidiaries and accordingly engages in business that may be forbidden to Armour by the Meat Packers Consent Decree of 1920, in itself and without any evidentiary showing as to the consequences, does not violate the Decree's prohibition against Armour's \"directly or indirectly... engaging in or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 44","2":"18"}},{"t":"case","label":"United States v. Atlantic Research Corp.","cite":"551 U.S. 128","y":2007,"id":"2006/06-562","sc":1,"op":5,"sum":"The Court ruled unanimously that Section 107(a) of CERCLA allows potentially responsible parties (PRPs) to sue other PRPs for cost recovery. The opinion by Justice Clarence Thomas affirmed the Eighth Circuit and ruled for Atlantic Research.","sumSrc":"Oyez","by":{"0":"passim","1":"37, 46","2":"3, 13, 21"}},{"t":"case","label":"United States v. Bridgestone Americas Tire Operations, LLC","cite":"2018 WL 5621496","y":2018,"court":"S.D. Ohio Oct. 30","by":{"0":"44"}},{"t":"case","label":"United States v. Briggs","cite":"141 S. Ct. 467","y":2020,"id":"2020/19-108","sc":1,"op":2,"sum":"Respondents’ prosecutions for military rape were timely commenced under the Uniform Code of Military Justice’s statute of limitations.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25, 30","2":"1"}},{"t":"case","label":"United States v. Goodrich Corp.","cite":"2021 WL 297577","y":2021,"court":"W.D. Ky. Jan. 28","by":{"0":"44"}},{"t":"case","label":"United States v. ITT Continental Baking Co.","cite":"420 U.S. 223","y":1975,"id":"1974/73-1290","sc":1,"sum":"\"Acquiring\" as used in the consent order means both the initial transaction and the maintaining of the rights obtained without resale, and therefore violation of the order is a \"continuing failure or neglect to obey\" an FTC order within the meaning of §§ 21 (1) and 45 (1) and thus subject to daily penalties thereunder.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"United States v. Savoy Senior Housing Corp.","cite":"2008 WL 631161","y":2008,"court":"W.D. Va. Mar. 6","by":{"0":"26"}},{"t":"case","label":"United States Department of Energy v. Ohio","cite":"503 U.S. 607","y":1992,"id":"1991/90-1341","sc":1,"ar":1,"sum":"Congress has not waived the National Government's sovereign immunity from liability for civil fines imposed by a State for past violations of the CWA or RCRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 23"}},{"t":"case","label":"United States Forest Service v. Cowpasture River Preservation Ass’n","cite":"140 S. Ct. 1837","y":2020,"id":"2019/18-1584","sc":1,"sum":"The Court held that the U.S. Forest Service has the authority to grant rights-of-way under the Mineral Leasing Act through lands traversed by the Appalachian Trail within national forests.","sumSrc":"Oyez","by":{"0":"27, 28","2":"8, 12"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"33 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/33/1311","subs":["(a)"],"stext":{"head":"§1311. Effluent limitations","paras":[[0,"(a) Illegality of pollutant discharges except in compliance with law"],[0,"Except as in compliance with this section and sections 1312, 1316, 1317, 1328, 1342, and 1344 of this title, the discharge of any pollutant by any person shall be unlawful."],[0,"(b) Timetable for achievement of objectives"],[0,"In order to carry out the objective of this chapter there shall be achieved—"],[1,"(1)(A) not later than July 1, 1977, effluent limitations for point sources, other than publicly owned treatment works, (i) which shall require the application of the best practicable control technology currently available as defined by the Administrator pursuant to section 1314(b) of this title, or (ii) in the case of a discharge into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, which shall require compliance with any applicable pretreatment requirements and any requirements under section 1317 of this title; and"],[1,"(B) for publicly owned treatment works in existence on July 1, 1977, or approved pursuant to section 1283 of this title prior to June 30, 1974 (for which construction must be completed within four years of approval), effluent limitations based upon secondary treatment as defined by the Administrator pursuant to section 1314(d)(1) of this title; or,"],[1,"(C) not later than July 1, 1977, any more stringent limitation, including those necessary to meet water quality standards, treatment standards, or schedules of compliance, established pursuant to any State law or regulations (under authority preserved by section 1370 of this title) or any other Federal law or regulation, or required to implement any applicable water quality standard established pursuant to this chapter."],[1,"(2)(A) for pollutants identified in subparagraphs (C), (D), and (F) of this paragraph, effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which (i) shall require application of the best available technology economically achievable for such category or class, which will result in reasonable further progress toward the national goal of eliminating the discharge of all pollutants, as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, which such effluent limitations shall require the elimination of discharges of all pollutants if the Administrator finds, on the basis of information available to him (including information developed pursuant to section 1325 of this title), that such elimination is technologically and economically achievable for a category or class of point sources as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, or (ii) in the case of the introduction of a pollutant into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, shall require compliance with any applicable pretreatment requirements and any other requirement under section 1317 of this title;"],[1,"(B) Repealed. Pub. L. 97–117, §21(b), Dec. 29, 1981, 95 Stat. 1632."],[1,"(C) with respect to all toxic pollutants referred to in table 1 of Committee Print Numbered 95–30 of the Committee on Public Works and Transportation of the House of Representatives compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(D) for all toxic pollutants listed under paragraph (1) of subsection (a) of section 1317 of this title which are not referred to in subparagraph (C) of this paragraph compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable, but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(E) as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989, compliance with effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which in the case of pollutants identified pursuant to section 1314(a)(4) of this title shall require application of the best conventional pollutant control technology as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(4) of this title; and"],[1,"(F) for all pollutants (other than those subject to subparagraphs (C), (D), or (E) of this paragraph) compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than 3 years after the date such limitations are established, and in no case later than March 31, 1989."],[1,"(3)(A) for effluent limitations under paragraph (1)(A)(i) of this subsection promulgated after January 1, 1982, and requiring a level of control substantially greater or based on fundamentally different control technology than under permits for an industrial category issued before such date, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989; and"],[1,"(B) for any effluent limitation in accordance with paragraph (1)(A)(i), (2)(A)(i), or (2)(E) of this subsection established only on the basis of section 1342(a)(1) of this title in a permit issued after February 4, 1987, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are established, and in no case later than March 31, 1989."],[0,"(c) Modification of timetable"],[0,"The Administrator may modify the requirements of subsection (b)(2)(A) of this section with respect to any point source for which a permit application is filed after July 1, 1977, upon a showing by the owner or operator of such point source satisfactory to the Administrator that such modified requirements (1) will represent the maximum use of technology within the economic capability of the owner or operator; and (2) will result in reasonable further progress toward the elimination of the discharge of pollutants."],[0,"(d) Review and revision of effluent limitations"],[0,"Any effluent limitation required by paragraph (2) of subsection (b) of this section shall be reviewed at least every five years and, if appropriate, revised pursuant to the procedure established under such paragraph."],[0,"(e) All point discharge source application of effluent limitations"],[0,"Effluent limitations established pursuant to this section or section 1312 of this title shall be applied to all point sources of discharge of pollutants in accordance with the provisions of this chapter."],[0,"(f) Illegality of discharge of radiological, chemical, or biological warfare agents, high-level radioactive waste, or medical waste"],[0,"Notwithstanding any other provisions of this chapter it shall be unlawful to discharge any radiological, chemical, or biological warfare agent, any high-level radioactive waste, or any medical waste, into the navigable waters."],[0,"(g) Modifications for certain nonconventional pollutants"],[0,"(1) General authority"],[1,"The Administrator, with the concurrence of the State, may modify the requirements of subsection (b)(2)(A) of this section with respect to the discharge from any point source of ammonia, chlorine, color, iron, and total phenols (4AAP) (when determined by the Administrator to be a pollutant covered by subsection (b)(2)(F)) and any other pollutant which the Administrator lists under paragraph (4) of this subsection."],[0,"(2) Requirements for granting modifications"],[1,"A modification under this subsection shall be granted only upon a showing by the owner or operator of a point source satisfactory to the Administrator that—"],[2,"(A) such modified requirements will result at a minimum in compliance with the requirements of subsection (b)(1)(A) or (C) of this section, whichever is applicable;"],[2,"(B) such modified requirements will not result in any additional requirements on any other point or nonpoint source; and"],[2,"(C) such modification will not interfere with the attainment or maintenance of that water quality which shall assure protection of public water supplies, and the protection and propagation of a balanced population of shellfish, fish, and wildlife, and allow recreational activities, in and on the water and such modification will not result in the discharge of pollutants in quantities which may reasonably be anticipated to pose an unacceptable risk to human health or the environment because of bioaccumulation, persistency in the environment, acute toxicity, chronic toxicity (including carcinogenicity, mutagenicity or teratogenicity), or synergistic propensities."],[0,"(3) Limitation on authority to apply for subsection (c) modification"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1311?type=usc&year=mostrecent&link-type=html"},"head":"§1311. Effluent limitations","tname":"Navigation and Navigable Waters","by":{"0":"36, 10","2":"10"}},{"t":"usc","label":"33 U.S.C. § 1319","url":"https://www.law.cornell.edu/uscode/text/33/1319","by":{"0":"9, 10, 36"}},{"t":"usc","label":"33 U.S.C. § 1321","url":"https://www.law.cornell.edu/uscode/text/33/1321","by":{"0":"37"}},{"t":"usc","label":"42 U.S.C. § 9601","url":"https://www.law.cornell.edu/uscode/text/42/9601","subs":["(14)","(21)","(23)","(24)","(25)","(27)","(32)","(7)","(8)","(10)","(20)(E)(i)","(20)(H)(iv)(III)","(35)(D)","(22)"],"stext":{"head":"§9601. Definitions","paras":[[0,"For purpose of this subchapter—"],[1,"(1) The term \"act of God\" means an unanticipated grave natural disaster or other natural phenomenon of an exceptional, inevitable, and irresistible character, the effects of which could not have been prevented or avoided by the exercise of due care or foresight."],[1,"(2) The term \"Administrator\" means the Administrator of the United States Environmental Protection Agency."],[1,"(3) The term \"barrel\" means forty-two United States gallons at sixty degrees Fahrenheit."],[1,"(4) The term \"claim\" means a demand in writing for a sum certain."],[1,"(5) The term \"claimant\" means any person who presents a claim for compensation under this chapter."],[1,"(6) The term \"damages\" means damages for injury or loss of natural resources as set forth in section 9607(a) or 9611(b) of this title."],[1,"(7) The term \"drinking water supply\" means any raw or finished water source that is or may be used by a public water system (as defined in the Safe Drinking Water Act [42 U.S.C. 300f et seq.]) or as drinking water by one or more individuals."],[1,"(8) The term \"environment\" means (A) the navigable waters, the waters of the contiguous zone, and the ocean waters of which the natural resources are under the exclusive management authority of the United States under the Magnuson-Stevens Fishery Conservation and Management Act [16 U.S.C. 1801 et seq.], and (B) any other surface water, ground water, drinking water supply, land surface or subsurface strata, or ambient air within the United States or under the jurisdiction of the United States."],[1,"(9) The term \"facility\" means (A) any building, structure, installation, equipment, pipe or pipeline (including any pipe into a sewer or publicly owned treatment works), well, pit, pond, lagoon, impoundment, ditch, landfill, storage container, motor vehicle, rolling stock, or aircraft, or (B) any site or area where a hazardous substance has been deposited, stored, disposed of, or placed, or otherwise come to be located; but does not include any consumer product in consumer use or any vessel."],[1,"(10) The term \"federally permitted release\" means (A) discharges in compliance with a permit under section 402 of the Federal Water Pollution Control Act [33 U.S.C. 1342], (B) discharges resulting from circumstances identified and reviewed and made part of the public record with respect to a permit issued or modified under section 402 of the Federal Water Pollution Control Act and subject to a condition of such permit, (C) continuous or anticipated intermittent discharges from a point source, identified in a permit or permit application under section 402 of the Federal Water Pollution Control Act, which are caused by events occurring within the scope of relevant operating or treatment systems, (D) discharges in compliance with a legally enforceable permit under section 404 of the Federal Water Pollution Control Act [33 U.S.C. 1344], (E) releases in compliance with a legally enforceable final permit issued pursuant to section 3005(a) through (d) of the Solid Waste Disposal Act [42 U.S.C. 6925(a)–(d)] from a hazardous waste treatment, storage, or disposal facility when such permit specifically identifies the hazardous substances and makes such substances subject to a standard of practice, control procedure or bioassay limitation or condition, or other control on the hazardous substances in such releases, (F) any release in compliance with a legally enforceable permit issued under section 1412 of title 33 of 1 section 1413 of title 33, (G) any injection of fluids authorized under Federal underground injection control programs or State programs submitted for Federal approval (and not disapproved by the Administrator of the Environmental Protection Agency) pursuant to part C of the Safe Drinking Water Act [42 U.S.C. 300h et seq.], (H) any emission into the air subject to a permit or control regulation under section 111 [42 U.S.C. 7411], section 112 [42 U.S.C. 7412], title I part C [42 U.S.C. 7470 et seq.], title I part D [42 U.S.C. 7501 et seq.], or State implementation plans submitted in accordance with section 110 of the Clean Air Act [42 U.S.C. 7410] (and not disapproved by the Administrator of the Environmental Protection Agency), including any schedule or waiver granted, promulgated, or approved under these sections, (I) any injection of fluids or other materials authorized under applicable State law (i) for the purpose of stimulating or treating wells for the production of crude oil, natural gas, or water, (ii) for the purpose of secondary, tertiary, or other enhanced recovery of crude oil or natural gas, or (iii) which are brought to the surface in conjunction with the production of crude oil or natural gas and which are reinjected, (J) the introduction of any pollutant into a publicly owned treatment works when such pollutant is specified in and in compliance with applicable pretreatment standards of section 307(b) or (c) of the Clean Water Act [33 U.S.C. 1317(b), (c)] and enforceable requirements in a pretreatment program submitted by a State or municipality for Federal approval under section 402 of such Act [33 U.S.C. 1342], and (K) any release of source, special nuclear, or byproduct material, as those terms are defined in the Atomic Energy Act of 1954 [42 U.S.C. 2011 et seq.], in compliance with a legally enforceable license, permit, regulation, or order issued pursuant to the Atomic Energy Act of 1954."],[1,"(11) The term \"Fund\" or \"Trust Fund\" means the Hazardous Substance Superfund established by section 9507 of title 26."],[1,"(12) The term \"ground water\" means water in a saturated zone or stratum beneath the surface of land or water."],[1,"(13) The term \"guarantor\" means any person, other than the owner or operator, who provides evidence of financial responsibility for an owner or operator under this chapter."],[1,"(14) The term \"hazardous substance\" means (A) any substance designated pursuant to section 311(b)(2)(A) of the Federal Water Pollution Control Act [33 U.S.C. 1321(b)(2)(A)], (B) any element, compound, mixture, solution, or substance designated pursuant to section 9602 of this title, (C) any hazardous waste having the characteristics identified under or listed pursuant to section 3001 of the Solid Waste Disposal Act [42 U.S.C. 6921] (but not including any waste the regulation of which under the Solid Waste Disposal Act [42 U.S.C. 6901 et seq.] has been suspended by Act of Congress), (D) any toxic pollutant listed under section 307(a) of the Federal Water Pollution Control Act [33 U.S.C. 1317(a)], (E) any hazardous air pollutant listed under section 112 of the Clean Air Act [42 U.S.C. 7412], and (F) any imminently hazardous chemical substance or mixture with respect to which the Administrator has taken action pursuant to section 7 of the Toxic Substances Control Act [15 U.S.C. 2606]. The term does not include petroleum, including crude oil or any fraction thereof which is not otherwise specifically listed or designated as a hazardous substance under subparagraphs (A) through (F) of this paragraph, and the term does not include natural gas, natural gas liquids, liquefied natural gas, or synthetic gas usable for fuel (or mixtures of natural gas and such synthetic gas)."],[1,"(15) The term \"navigable waters\" or \"navigable waters of the United States\" means the waters of the United States, including the territorial seas."],[1,"(16) The term \"natural resources\" means land, fish, wildlife, biota, air, water, ground water, drinking water supplies, and other such resources belonging to, managed by, held in trust by, appertaining to, or otherwise controlled by the United States (including the resources of the fishery conservation zone established by the Magnuson-Stevens Fishery Conservation and Management Act [16 U.S.C. 1801 et seq.]), any State or local government, any foreign government, any Indian tribe, or, if such resources are subject to a trust restriction on alienation, any member of an Indian tribe."],[1,"(17) The term \"offshore facility\" means any facility of any kind located in, on, or under, any of the navigable waters of the United States, and any facility of any kind which is subject to the jurisdiction of the United States and is located in, on, or under any other waters, other than a vessel or a public vessel."],[1,"(18) The term \"onshore facility\" means any facility (including, but not limited to, motor vehicles and rolling stock) of any kind located in, on, or under, any land or nonnavigable waters within the United States."],[1,"(19) The term \"otherwise subject to the jurisdiction of the United States\" means subject to the jurisdiction of the United States by virtue of United States citizenship, United States vessel documentation or numbering, or as provided by international agreement to which the United States is a party."],[1,"(20)(A) The term \"owner or operator\" means (i) in the case of a vessel, any person owning, operating, or chartering by demise, such vessel, (ii) in the case of an onshore facility or an offshore facility, any person owning or operating such facility, and (iii) in the case of any facility, title or control of which was conveyed due to bankruptcy, foreclosure, tax delinquency, abandonment, or similar means to a unit of State or local government, any person who owned, operated, or otherwise controlled activities at such facility immediately beforehand. Such term does not include a person, who, without participating in the management of a vessel or facility, holds indicia of ownership primarily to protect his security interest in the vessel or facility."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9601?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9601. Definitions","tname":"The Public Health and Welfare","by":{"0":"1, 37, 4, 4, 17, 37, 4, 17, 37, 3, 17, 32, 36, 4, 17","1":"2, 21, 21, 21, 21, 21, 21, 2, 2, 3, 17, 20, 24, 26, 2, 3, 17, 20, 24, 26, 2, 3, 17, 20, 24, 26, 2, 3, 17, 20, 24, 26","2":"4, 4, 4, 10, 4, 4, 13"}},{"t":"usc","label":"42 U.S.C. § 9604","url":"https://www.law.cornell.edu/uscode/text/42/9604","subs":["(k)(12)"],"stext":{"head":"§9604. Response authorities","paras":[[0,"(a) Removal and other remedial action by President; applicability of national contingency plan; response by potentially responsible parties; public health threats; limitations on response; exception"],[0,"(1) Whenever (A) any hazardous substance is released or there is a substantial threat of such a release into the environment, or (B) there is a release or substantial threat of release into the environment of any pollutant or contaminant which may present an imminent and substantial danger to the public health or welfare, the President is authorized to act, consistent with the national contingency plan, to remove or arrange for the removal of, and provide for remedial action relating to such hazardous substance, pollutant, or contaminant at any time (including its removal from any contaminated natural resource), or take any other response measure consistent with the national contingency plan which the President deems necessary to protect the public health or welfare or the environment. When the President determines that such action will be done properly and promptly by the owner or operator of the facility or vessel or by any other responsible party, the President may allow such person to carry out the action, conduct the remedial investigation, or conduct the feasibility study in accordance with section 9622 of this title. No remedial investigation or feasibility study (RI/FS) shall be authorized except on a determination by the President that the party is qualified to conduct the RI/FS and only if the President contracts with or arranges for a qualified person to assist the President in overseeing and reviewing the conduct of such RI/FS and if the responsible party agrees to reimburse the Fund for any cost incurred by the President under, or in connection with, the oversight contract or arrangement. In no event shall a potentially responsible party be subject to a lesser standard of liability, receive preferential treatment, or in any other way, whether direct or indirect, benefit from any such arrangements as a response action contractor, or as a person hired or retained by such a response action contractor, with respect to the release or facility in question. The President shall give primary attention to those releases which the President deems may present a public health threat."],[0,"(2) Removal Action.—Any removal action undertaken by the President under this subsection (or by any other person referred to in section 9622 of this title) should, to the extent the President deems practicable, contribute to the efficient performance of any long term remedial action with respect to the release or threatened release concerned."],[0,"(3) Limitations on Response.—The President shall not provide for a removal or remedial action under this section in response to a release or threat of release—"],[1,"(A) of a naturally occurring substance in its unaltered form, or altered solely through naturally occurring processes or phenomena, from a location where it is naturally found;"],[1,"(B) from products which are part of the structure of, and result in exposure within, residential buildings or business or community structures; or"],[1,"(C) into public or private drinking water supplies due to deterioration of the system through ordinary use."],[0,"(4) Exception to Limitations.—Notwithstanding paragraph (3) of this subsection, to the extent authorized by this section, the President may respond to any release or threat of release if in the President's discretion, it constitutes a public health or environmental emergency and no other person with the authority and capability to respond to the emergency will do so in a timely manner."],[0,"(b) Investigations, monitoring, coordination, etc., by President"],[0,"(1) Information; studies and investigations"],[1,"Whenever the President is authorized to act pursuant to subsection (a) of this section, or whenever the President has reason to believe that a release has occurred or is about to occur, or that illness, disease, or complaints thereof may be attributable to exposure to a hazardous substance, pollutant, or contaminant and that a release may have occurred or be occurring, he may undertake such investigations, monitoring, surveys, testing, and other information gathering as he may deem necessary or appropriate to identify the existence and extent of the release or threat thereof, the source and nature of the hazardous substances, pollutants or contaminants involved, and the extent of danger to the public health or welfare or to the environment. In addition, the President may undertake such planning, legal, fiscal, economic, engineering, architectural, and other studies or investigations as he may deem necessary or appropriate to plan and direct response actions, to recover the costs thereof, and to enforce the provisions of this chapter."],[0,"(2) Coordination of investigations"],[1,"The President shall promptly notify the appropriate Federal and State natural resource trustees of potential damages to natural resources resulting from releases under investigation pursuant to this section and shall seek to coordinate the assessments, investigations, and planning under this section with such Federal and State trustees."],[0,"(c) Criteria for continuance of obligations from Fund over specified amount for response actions; consultation by President with affected States; contracts or cooperative agreements by States with President prior to remedial actions; cost-sharing agreements; selection by President of remedial actions; State credits: granting of credit, expenses before listing or agreement, response actions between 1978 and 1980, State expenses after December 11, 1980, in excess of 10 percent of costs, item-by-item approval, use of credits; operation and maintenance; limitation on source of funds for O&M; recontracting; siting"],[0,"(1) Unless (A) the President finds that (i) continued response actions are immediately required to prevent, limit, or mitigate an emergency, (ii) there is an immediate risk to public health or welfare or the environment, and (iii) such assistance will not otherwise be provided on a timely basis, or (B) the President has determined the appropriate remedial actions pursuant to paragraph (2) of this subsection and the State or States in which the source of the release is located have complied with the requirements of paragraph (3) of this subsection, or (C) continued response action is otherwise appropriate and consistent with the remedial action to be taken 1 obligations from the Fund, other than those authorized by subsection (b) of this section, shall not continue after $2,000,000 has been obligated for response actions or 12 months has elapsed from the date of initial response to a release or threatened release of hazardous substances."],[0,"(2) The President shall consult with the affected State or States before determining any appropriate remedial action to be taken pursuant to the authority granted under subsection (a) of this section."],[0,"(3) The President shall not provide any remedial actions pursuant to this section unless the State in which the release occurs first enters into a contract or cooperative agreement with the President providing assurances deemed adequate by the President that (A) the State will assure all future maintenance of the removal and remedial actions provided for the expected life of such actions as determined by the President; (B) the State will assure the availability of a hazardous waste disposal facility acceptable to the President and in compliance with the requirements of subtitle C of the Solid Waste Disposal Act [42 U.S.C. 6921 et seq.] for any necessary offsite storage, destruction, treatment, or secure disposition of the hazardous substances; and (C) the State will pay or assure payment of (i) 10 per centum of the costs of the remedial action, including all future maintenance, or (ii) 50 percent (or such greater amount as the President may determine appropriate, taking into account the degree of responsibility of the State or political subdivision for the release) of any sums expended in response to a release at a facility, that was operated by the State or a political subdivision thereof, either directly or through a contractual relationship or otherwise, at the time of any disposal of hazardous substances therein. For the purpose of clause (ii) of this subparagraph, the term \"facility\" does not include navigable waters or the beds underlying those waters. In the case of remedial action to be taken on land or water held by an Indian tribe, held by the United States in trust for Indians, held by a member of an Indian tribe (if such land or water is subject to a trust restriction on alienation), or otherwise within the borders of an Indian reservation, the requirements of this paragraph for assurances regarding future maintenance and cost-sharing shall not apply, and the President shall provide the assurance required by this paragraph regarding the availability of a hazardous waste disposal facility."],[0,"(4) Selection of Remedial Action.—The President shall select remedial actions to carry out this section in accordance with section 9621 of this title (relating to cleanup standards)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9604?type=usc&year=mostrecent&link-type=html"},"head":"§9604. Response authorities","tname":"The Public Health and Welfare","by":{"0":"3","1":"2, 3, 17, 20, 24, 26, 2, 3, 17, 20, 24, 26"}},{"t":"usc","label":"42 U.S.C. § 9605","url":"https://www.law.cornell.edu/uscode/text/42/9605","subs":["(b)"],"stext":{"head":"§9605. National contingency plan","paras":[[0,"(a) Revision and republication"],[0,"Within one hundred and eighty days after December 11, 1980, the President shall, after notice and opportunity for public comments, revise and republish the national contingency plan for the removal of oil and hazardous substances, originally prepared and published pursuant to section 1321 of title 33, to reflect and effectuate the responsibilities and powers created by this chapter, in addition to those matters specified in section 1321(c)(2) 1 of title 33. Such revision shall include a section of the plan to be known as the national hazardous substance response plan which shall establish procedures and standards for responding to releases of hazardous substances, pollutants, and contaminants, which shall include at a minimum:"],[1,"(1) methods for discovering and investigating facilities at which hazardous substances have been disposed of or otherwise come to be located;"],[1,"(2) methods for evaluating, including analyses of relative cost, and remedying any releases or threats of releases from facilities which pose substantial danger to the public health or the environment;"],[1,"(3) methods and criteria for determining the appropriate extent of removal, remedy, and other measures authorized by this chapter;"],[1,"(4) appropriate roles and responsibilities for the Federal, State, and local governments and for interstate and nongovernmental entities in effectuating the plan;"],[1,"(5) provision for identification, procurement, maintenance, and storage of response equipment and supplies;"],[1,"(6) a method for and assignment of responsibility for reporting the existence of such facilities which may be located on federally owned or controlled properties and any releases of hazardous substances from such facilities;"],[1,"(7) means of assuring that remedial action measures are cost-effective over the period of potential exposure to the hazardous substances or contaminated materials;"],[1,"(8)(A) criteria for determining priorities among releases or threatened releases throughout the United States for the purpose of taking remedial action and, to the extent practicable taking into account the potential urgency of such action, for the purpose of taking removal action. Criteria and priorities under this paragraph shall be based upon relative risk or danger to public health or welfare or the environment, in the judgment of the President, taking into account to the extent possible the population at risk, the hazard potential of the hazardous substances at such facilities, the potential for contamination of drinking water supplies, the potential for direct human contact, the potential for destruction of sensitive ecosystems, the damage to natural resources which may affect the human food chain and which is associated with any release or threatened release, the contamination or potential contamination of the ambient air which is associated with the release or threatened release, State preparedness to assume State costs and responsibilities, and other appropriate factors;"],[1,"(B) based upon the criteria set forth in subparagraph (A) of this paragraph, the President shall list as part of the plan national priorities among the known releases or threatened releases throughout the United States and shall revise the list no less often than annually. Within one year after December 11, 1980, and annually thereafter, each State shall establish and submit for consideration by the President priorities for remedial action among known releases and potential releases in that State based upon the criteria set forth in subparagraph (A) of this paragraph. In assembling or revising the national list, the President shall consider any priorities established by the States. To the extent practicable, the highest priority facilities shall be designated individually and shall be referred to as the \"top priority among known response targets\", and, to the extent practicable, shall include among the one hundred highest priority facilities one such facility from each State which shall be the facility designated by the State as presenting the greatest danger to public health or welfare or the environment among the known facilities in such State. A State shall be allowed to designate its highest priority facility only once. Other priority facilities or incidents may be listed singly or grouped for response priority purposes;"],[1,"(9) specified roles for private organizations and entities in preparation for response and in responding to releases of hazardous substances, including identification of appropriate qualifications and capacity therefor and including consideration of minority firms in accordance with subsection (f); and"],[1,"(10) standards and testing procedures by which alternative or innovative treatment technologies can be determined to be appropriate for utilization in response actions authorized by this chapter."],[0,"The plan shall specify procedures, techniques, materials, equipment, and methods to be employed in identifying, removing, or remedying releases of hazardous substances comparable to those required under section 1321(c)(2)(F) and (G) and (j)(1) of title 33. Following publication of the revised national contingency plan, the response to and actions to minimize damage from hazardous substances releases shall, to the greatest extent possible, be in accordance with the provisions of the plan. The President may, from time to time, revise and republish the national contingency plan."],[0,"(b) Revision of plan"],[0,"Not later than 18 months after the enactment of the Superfund Amendments and Reauthorization Act of 1986 [October 17, 1986], the President shall revise the National Contingency Plan to reflect the requirements of such amendments. The portion of such Plan known as \"the National Hazardous Substance Response Plan\" shall be revised to provide procedures and standards for remedial actions undertaken pursuant to this chapter which are consistent with amendments made by the Superfund Amendments and Reauthorization Act of 1986 relating to the selection of remedial action."],[0,"(c) Hazard ranking system"],[0,"(1) Revision"],[1,"Not later than 18 months after October 17, 1986, and after publication of notice and opportunity for submission of comments in accordance with section 553 of title 5, the President shall by rule promulgate amendments to the hazard ranking system in effect on September 1, 1984. Such amendments shall assure, to the maximum extent feasible, that the hazard ranking system accurately assesses the relative degree of risk to human health and the environment posed by sites and facilities subject to review. The President shall establish an effective date for the amended hazard ranking system which is not later than 24 months after October 17, 1986. Such amended hazard ranking system shall be applied to any site or facility to be newly listed on the National Priorities List after the effective date established by the President. Until such effective date of the regulations, the hazard ranking system in effect on September 1, 1984, shall continue in full force and effect."],[0,"(2) Health assessment of water contamination risks"],[1,"In carrying out this subsection, the President shall ensure that the human health risks associated with the contamination or potential contamination (either directly or as a result of the runoff of any hazardous substance or pollutant or contaminant from sites or facilities) of surface water are appropriately assessed where such surface water is, or can be, used for recreation or potable water consumption. In making the assessment required pursuant to the preceding sentence, the President shall take into account the potential migration of any hazardous substance or pollutant or contaminant through such surface water to downstream sources of drinking water."],[0,"(3) Reevaluation not required"],[1,"The President shall not be required to reevaluate, after October 17, 1986, the hazard ranking of any facility which was evaluated in accordance with the criteria under this section before the effective date of the amendments to the hazard ranking system under this subsection and which was assigned a national priority under the National Contingency Plan."],[0,"(4) New information"],[1,"Nothing in paragraph (3) shall preclude the President from taking new information into account in undertaking response actions under this chapter."],[0,"(d) Petition for assessment of release"],[0,"Any person who is, or may be, affected by a release or threatened release of a hazardous substance or pollutant or contaminant, may petition the President to conduct a preliminary assessment of the hazards to public health and the environment which are associated with such release or threatened release. If the President has not previously conducted a preliminary assessment of such release, the President shall, within 12 months after the receipt of any such petition, complete such assessment or provide an explanation of why the assessment is not appropriate. If the preliminary assessment indicates that the release or threatened release concerned may pose a threat to human health or the environment, the President shall promptly evaluate such release or threatened release in accordance with the hazard ranking system referred to in paragraph (8)(A) of subsection (a) to determine the national priority of such release or threatened release."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9605?type=usc&year=mostrecent&link-type=html"},"head":"§9605. National contingency plan","tname":"The Public Health and Welfare","by":{"0":"3","1":"2, 3, 17, 20, 24, 26"}},{"t":"usc","label":"42 U.S.C. § 9606","url":"https://www.law.cornell.edu/uscode/text/42/9606","subs":["(a)"],"stext":{"head":"§9606. Abatement actions","paras":[[0,"(a) Maintenance, jurisdiction, etc."],[0,"In addition to any other action taken by a State or local government, when the President determines that there may be an imminent and substantial endangerment to the public health or welfare or the environment because of an actual or threatened release of a hazardous substance from a facility, he may require the Attorney General of the United States to secure such relief as may be necessary to abate such danger or threat, and the district court of the United States in the district in which the threat occurs shall have jurisdiction to grant such relief as the public interest and the equities of the case may require. The President may also, after notice to the affected State, take other action under this section including, but not limited to, issuing such orders as may be necessary to protect public health and welfare and the environment."],[0,"(b) Fines; reimbursement"],[0,"(1) Any person who, without sufficient cause, willfully violates, or fails or refuses to comply with, any order of the President under subsection (a) may, in an action brought in the appropriate United States district court to enforce such order, be fined not more than $25,000 for each day in which such violation occurs or such failure to comply continues."],[0,"(2)(A) Any person who receives and complies with the terms of any order issued under subsection (a) may, within 60 days after completion of the required action, petition the President for reimbursement from the Fund for the reasonable costs of such action, plus interest. Any interest payable under this paragraph shall accrue on the amounts expended from the date of expenditure at the same rate as specified for interest on investments of the Hazardous Substance Superfund established under subchapter A of chapter 98 of title 26."],[0,"(B) If the President refuses to grant all or part of a petition made under this paragraph, the petitioner may within 30 days of receipt of such refusal file an action against the President in the appropriate United States district court seeking reimbursement from the Fund."],[0,"(C) Except as provided in subparagraph (D), to obtain reimbursement, the petitioner shall establish by a preponderance of the evidence that it is not liable for response costs under section 9607(a) of this title and that costs for which it seeks reimbursement are reasonable in light of the action required by the relevant order."],[0,"(D) A petitioner who is liable for response costs under section 9607(a) of this title may also recover its reasonable costs of response to the extent that it can demonstrate, on the administrative record, that the President's decision in selecting the response action ordered was arbitrary and capricious or was otherwise not in accordance with law. Reimbursement awarded under this subparagraph shall include all reasonable response costs incurred by the petitioner pursuant to the portions of the order found to be arbitrary and capricious or otherwise not in accordance with law."],[0,"(E) Reimbursement awarded by a court under subparagraph (C) or (D) may include appropriate costs, fees, and other expenses in accordance with subsections (a) and (d) of section 2412 of title 28."],[0,"(c) Guidelines for using imminent hazard, enforcement, and emergency response authorities; promulgation by Administrator of EPA, scope, etc."],[0,"Within one hundred and eighty days after December 11, 1980, the Administrator of the Environmental Protection Agency shall, after consultation with the Attorney General, establish and publish guidelines for using the imminent hazard, enforcement, and emergency response authorities of this section and other existing statutes administered by the Administrator of the Environmental Protection Agency to effectuate the responsibilities and powers created by this chapter. Such guidelines shall to the extent practicable be consistent with the national hazardous substance response plan, and shall include, at a minimum, the assignment of responsibility for coordinating response actions with the issuance of administrative orders, enforcement of standards and permits, the gathering of information, and other imminent hazard and emergency powers authorized by (1) sections 1321(c)(2),1 1318, 1319, and 1364(a) of title 33, (2) sections 6927, 6928, 6934, and 6973 of this title, (3) sections 300j–4 and 300i of this title, (4) sections 7413, 7414, and 7603 of this title, and (5) section 2606 of title 15."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9606?type=usc&year=mostrecent&link-type=html"},"head":"§9606. Abatement actions","tname":"The Public Health and Welfare","by":{"0":"1, 3, 17, 25","1":"2, 3, 17, 20, 24, 26, 43"}},{"t":"usc","label":"42 U.S.C. § 9607","url":"https://www.law.cornell.edu/uscode/text/42/9607","subs":["(a)","(a)(4)(A)","(a)(4)(B)","(l)(2)(A)"],"stext":{"head":"§9607. Liability","paras":[[0,"(a) Covered persons; scope; recoverable costs and damages; interest rate; \"comparable maturity\" date"],[0,"Notwithstanding any other provision or rule of law, and subject only to the defenses set forth in subsection (b) of this section—"],[1,"(1) the owner and operator of a vessel or a facility,"],[1,"(2) any person who at the time of disposal of any hazardous substance owned or operated any facility at which such hazardous substances were disposed of,"],[1,"(3) any person who by contract, agreement, or otherwise arranged for disposal or treatment, or arranged with a transporter for transport for disposal or treatment, of hazardous substances owned or possessed by such person, by any other party or entity, at any facility or incineration vessel owned or operated by another party or entity and containing such hazardous substances, and"],[1,"(4) any person who accepts or accepted any hazardous substances for transport to disposal or treatment facilities, incineration vessels or sites selected by such person, from which there is a release, or a threatened release which causes the incurrence of response costs, of a hazardous substance, shall be liable for—"],[2,"(A) all costs of removal or remedial action incurred by the United States Government or a State or an Indian tribe not inconsistent with the national contingency plan;"],[2,"(B) any other necessary costs of response incurred by any other person consistent with the national contingency plan;"],[2,"(C) damages for injury to, destruction of, or loss of natural resources, including the reasonable costs of assessing such injury, destruction, or loss resulting from such a release; and"],[2,"(D) the costs of any health assessment or health effects study carried out under section 9604(i) of this title."],[0,"The amounts recoverable in an action under this section shall include interest on the amounts recoverable under subparagraphs (A) through (D). Such interest shall accrue from the later of (i) the date payment of a specified amount is demanded in writing, or (ii) the date of the expenditure concerned. The rate of interest on the outstanding unpaid balance of the amounts recoverable under this section shall be the same rate as is specified for interest on investments of the Hazardous Substance Superfund established under subchapter A of chapter 98 of title 26. For purposes of applying such amendments to interest under this subsection, the term \"comparable maturity\" shall be determined with reference to the date on which interest accruing under this subsection commences."],[0,"(b) Defenses"],[0,"There shall be no liability under subsection (a) of this section for a person otherwise liable who can establish by a preponderance of the evidence that the release or threat of release of a hazardous substance and the damages resulting therefrom were caused solely by—"],[1,"(1) an act of God;"],[1,"(2) an act of war;"],[1,"(3) an act or omission of a third party other than an employee or agent of the defendant, or than one whose act or omission occurs in connection with a contractual relationship, existing directly or indirectly, with the defendant (except where the sole contractual arrangement arises from a published tariff and acceptance for carriage by a common carrier by rail), if the defendant establishes by a preponderance of the evidence that (a) he exercised due care with respect to the hazardous substance concerned, taking into consideration the characteristics of such hazardous substance, in light of all relevant facts and circumstances, and (b) he took precautions against foreseeable acts or omissions of any such third party and the consequences that could foreseeably result from such acts or omissions; or"],[1,"(4) any combination of the foregoing paragraphs."],[0,"(c) Determination of amounts"],[0,"(1) Except as provided in paragraph (2) of this subsection, the liability under this section of an owner or operator or other responsible person for each release of a hazardous substance or incident involving release of a hazardous substance shall not exceed—"],[1,"(A) for any vessel, other than an incineration vessel, which carries any hazardous substance as cargo or residue, $300 per gross ton, or $5,000,000, whichever is greater;"],[1,"(B) for any other vessel, other than an incineration vessel, $300 per gross ton, or $500,000, whichever is greater;"],[1,"(C) for any motor vehicle, aircraft, hazardous liquid pipeline facility (as defined in section 60101(a) of title 49), or rolling stock, $50,000,000 or such lesser amount as the President shall establish by regulation, but in no event less than $5,000,000 (or, for releases of hazardous substances as defined in section 9601(14)(A) of this title into the navigable waters, $8,000,000). Such regulations shall take into account the size, type, location, storage, and handling capacity and other matters relating to the likelihood of release in each such class and to the economic impact of such limits on each such class; or"],[1,"(D) for any incineration vessel or any facility other than those specified in subparagraph (C) of this paragraph, the total of all costs of response plus $50,000,000 for any damages under this subchapter."],[0,"(2) Notwithstanding the limitations in paragraph (1) of this subsection, the liability of an owner or operator or other responsible person under this section shall be the full and total costs of response and damages, if (A)(i) the release or threat of release of a hazardous substance was the result of willful misconduct or willful negligence within the privity or knowledge of such person, or (ii) the primary cause of the release was a violation (within the privity or knowledge of such person) of applicable safety, construction, or operating standards or regulations; or (B) such person fails or refuses to provide all reasonable cooperation and assistance requested by a responsible public official in connection with response activities under the national contingency plan with respect to regulated carriers subject to the provisions of title 49 or vessels subject to the provisions of title 33 or 46, subparagraph (A)(ii) of this paragraph shall be deemed to refer to Federal standards or regulations."],[0,"(3) If any person who is liable for a release or threat of release of a hazardous substance fails without sufficient cause to properly provide removal or remedial action upon order of the President pursuant to section 9604 or 9606 of this title, such person may be liable to the United States for punitive damages in an amount at least equal to, and not more than three times, the amount of any costs incurred by the Fund as a result of such failure to take proper action. The President is authorized to commence a civil action against any such person to recover the punitive damages, which shall be in addition to any costs recovered from such person pursuant to section 9612(c) of this title. Any moneys received by the United States pursuant to this subsection shall be deposited in the Fund."],[0,"(d) Rendering care or advice"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), no person shall be liable under this subchapter for costs or damages as a result of actions taken or omitted in the course of rendering care, assistance, or advice in accordance with the National Contingency Plan (\"NCP\") or at the direction of an onscene coordinator appointed under such plan, with respect to an incident creating a danger to public health or welfare or the environment as a result of any releases of a hazardous substance or the threat thereof. This paragraph shall not preclude liability for costs or damages as the result of negligence on the part of such person."],[0,"(2) State and local governments"],[1,"No State or local government shall be liable under this subchapter for costs or damages as a result of actions taken in response to an emergency created by the release or threatened release of a hazardous substance generated by or from a facility owned by another person. This paragraph shall not preclude liability for costs or damages as a result of gross negligence or intentional misconduct by the State or local government. For the purpose of the preceding sentence, reckless, willful, or wanton misconduct shall constitute gross negligence."],[0,"(3) Savings provision"],[1,"This subsection shall not alter the liability of any person covered by the provisions of paragraph (1), (2), (3), or (4) of subsection (a) of this section with respect to the release or threatened release concerned."],[0,"(e) Indemnification, hold harmless, etc., agreements or conveyances; subrogation rights"],[0,"(1) No indemnification, hold harmless, or similar agreement or conveyance shall be effective to transfer from the owner or operator of any vessel or facility or from any person who may be liable for a release or threat of release under this section, to any other person the liability imposed under this section. Nothing in this subsection shall bar any agreement to insure, hold harmless, or indemnify a party to such agreement for any liability under this section."],[0,"(2) Nothing in this subchapter, including the provisions of paragraph (1) of this subsection, shall bar a cause of action that an owner or operator or any other person subject to liability under this section, or a guarantor, has or would have, by reason of subrogation or otherwise against any person."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9607?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9607. Liability","tname":"The Public Health and Welfare","by":{"0":"1, 4, 25, 4, 17, 27, 4, 17","1":"43, 43, 43, 43","2":"13"}},{"t":"usc","label":"42 U.S.C. § 9613","url":"https://www.law.cornell.edu/uscode/text/42/9613","subs":["(f)","(f)(1)","(f)(2)","(f)(3)","(f)(3)(B)","(f)(3)(C)","(g)(2)(B)","(g)(3)(A)","(g)(3)(B)","(a)","(b)","(c)","(d)","(e)","(g)(1)","(g)(3)","(h)","(i)","(k)(2)(C)"],"stext":{"head":"§9613. Civil proceedings","paras":[[0,"(a) Review of regulations in Circuit Court of Appeals of the United States for the District of Columbia"],[0,"Review of any regulation promulgated under this chapter may be had upon application by any interested person only in the Circuit Court of Appeals of the United States for the District of Columbia. Any such application shall be made within ninety days from the date of promulgation of such regulations. Any matter with respect to which review could have been obtained under this subsection shall not be subject to judicial review in any civil or criminal proceeding for enforcement or to obtain damages or recovery of response costs."],[0,"(b) Jurisdiction; venue"],[0,"Except as provided in subsections (a) and (h) of this section, the United States district courts shall have exclusive original jurisdiction over all controversies arising under this chapter, without regard to the citizenship of the parties or the amount in controversy. Venue shall lie in any district in which the release or damages occurred, or in which the defendant resides, may be found, or has his principal office. For the purposes of this section, the Fund shall reside in the District of Columbia."],[0,"(c) Controversies or other matters resulting from tax collection or tax regulation review"],[0,"The provisions of subsections (a) and (b) of this section shall not apply to any controversy or other matter resulting from the assessment of collection of any tax, as provided by subchapter II 1 of this chapter, or to the review of any regulation promulgated under title 26."],[0,"(d) Litigation commenced prior to December 11, 1980"],[0,"No provision of this chapter shall be deemed or held to moot any litigation concerning any release of any hazardous substance, or any damages associated therewith, commenced prior to December 11, 1980."],[0,"(e) Nationwide service of process"],[0,"In any action by the United States under this chapter, process may be served in any district where the defendant is found, resides, transacts business, or has appointed an agent for the service of process."],[0,"(f) Contribution"],[0,"(1) Contribution"],[1,"Any person may seek contribution from any other person who is liable or potentially liable under section 9607(a) of this title, during or following any civil action under section 9606 of this title or under section 9607(a) of this title. Such claims shall be brought in accordance with this section and the Federal Rules of Civil Procedure, and shall be governed by Federal law. In resolving contribution claims, the court may allocate response costs among liable parties using such equitable factors as the court determines are appropriate. Nothing in this subsection shall diminish the right of any person to bring an action for contribution in the absence of a civil action under section 9606 of this title or section 9607 of this title."],[0,"(2) Settlement"],[1,"A person who has resolved its liability to the United States or a State in an administrative or judicially approved settlement shall not be liable for claims for contribution regarding matters addressed in the settlement. Such settlement does not discharge any of the other potentially liable persons unless its terms so provide, but it reduces the potential liability of the others by the amount of the settlement."],[0,"(3) Persons not party to settlement"],[1,"(A) If the United States or a State has obtained less than complete relief from a person who has resolved its liability to the United States or the State in an administrative or judicially approved settlement, the United States or the State may bring an action against any person who has not so resolved its liability."],[1,"(B) A person who has resolved its liability to the United States or a State for some or all of a response action or for some or all of the costs of such action in an administrative or judicially approved settlement may seek contribution from any person who is not party to a settlement referred to in paragraph (2)."],[1,"(C) In any action under this paragraph, the rights of any person who has resolved its liability to the United States or a State shall be subordinate to the rights of the United States or the State. Any contribution action brought under this paragraph shall be governed by Federal law."],[0,"(g) Period in which action may be brought"],[0,"(1) Actions for natural resource damages"],[1,"Except as provided in paragraphs (3) and (4), no action may be commenced for damages (as defined in section 9601(6) of this title) under this chapter, unless that action is commenced within 3 years after the later of the following:"],[2,"(A) The date of the discovery of the loss and its connection with the release in question."],[2,"(B) The date on which regulations are promulgated under section 9651(c) of this title."],[1,"With respect to any facility listed on the National Priorities List (NPL), any Federal facility identified under section 9620 of this title (relating to Federal facilities), or any vessel or facility at which a remedial action under this chapter is otherwise scheduled, an action for damages under this chapter must be commenced within 3 years after the completion of the remedial action (excluding operation and maintenance activities) in lieu of the dates referred to in subparagraph (A) or (B). In no event may an action for damages under this chapter with respect to such a vessel or facility be commenced (i) prior to 60 days after the Federal or State natural resource trustee provides to the President and the potentially responsible party a notice of intent to file suit, or (ii) before selection of the remedial action if the President is diligently proceeding with a remedial investigation and feasibility study under section 9604(b) of this title or section 9620 of this title (relating to Federal facilities). The limitation in the preceding sentence on commencing an action before giving notice or before selection of the remedial action does not apply to actions filed on or before October 17, 1986."],[0,"(2) Actions for recovery of costs"],[1,"An initial action for recovery of the costs referred to in section 9607 of this title must be commenced—"],[2,"(A) for a removal action, within 3 years after completion of the removal action, except that such cost recovery action must be brought within 6 years after a determination to grant a waiver under section 9604(c)(1)(C) of this title for continued response action; and"],[2,"(B) for a remedial action, within 6 years after initiation of physical on-site construction of the remedial action, except that, if the remedial action is initiated within 3 years after the completion of the removal action, costs incurred in the removal action may be recovered in the cost recovery action brought under this subparagraph."],[1,"In any such action described in this subsection, the court shall enter a declaratory judgment on liability for response costs or damages that will be binding on any subsequent action or actions to recover further response costs or damages. A subsequent action or actions under section 9607 of this title for further response costs at the vessel or facility may be maintained at any time during the response action, but must be commenced no later than 3 years after the date of completion of all response action. Except as otherwise provided in this paragraph, an action may be commenced under section 9607 of this title for recovery of costs at any time after such costs have been incurred."],[0,"(3) Contribution"],[1,"No action for contribution for any response costs or damages may be commenced more than 3 years after—"],[2,"(A) the date of judgment in any action under this chapter for recovery of such costs or damages, or"],[2,"(B) the date of an administrative order under section 9622(g) of this title (relating to de minimis settlements) or 9622(h) of this title (relating to cost recovery settlements) or entry of a judicially approved settlement with respect to such costs or damages."],[0,"(4) Subrogation"],[1,"No action based on rights subrogated pursuant to this section by reason of payment of a claim may be commenced under this subchapter more than 3 years after the date of payment of such claim."],[0,"(5) Actions to recover indemnification payments"],[1,"Notwithstanding any other provision of this subsection, where a payment pursuant to an indemnification agreement with a response action contractor is made under section 9619 of this title, an action under section 9607 of this title for recovery of such indemnification payment from a potentially responsible party may be brought at any time before the expiration of 3 years from the date on which such payment is made."],[0,"(6) Minors and incompetents"],[1,"The time limitations contained herein shall not begin to run—"],[2,"(A) against a minor until the earlier of the date when such minor reaches 18 years of age or the date on which a legal representative is duly appointed for such minor, or"],[2,"(B) against an incompetent person until the earlier of the date on which such incompetent's incompetency ends or the date on which a legal representative is duly appointed for such incompetent."],[0,"(h) Timing of review"],[0,"No Federal court shall have jurisdiction under Federal law other than under section 1332 of title 28 (relating to diversity of citizenship jurisdiction) or under State law which is applicable or relevant and appropriate under section 9621 of this title (relating to cleanup standards) to review any challenges to removal or remedial action selected under section 9604 of this title, or to review any order issued under section 9606(a) of this title, in any action except one of the following:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9613?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9613. Civil proceedings","tname":"The Public Health and Welfare","by":{"0":"5, 25, passim, 5, 35, 5, passim, 28, 5, 6, 6, 47","1":"43, 43, 43, 43, 43, 43, 43, 43, 43, 43, 43, 21, 21, 21, 21, 21, 21, 21, 21, 21, 21, 21","2":"2, 2, 5, 2, 1, 7, 13, 14, 17"}},{"t":"usc","label":"42 U.S.C. § 9614","url":"https://www.law.cornell.edu/uscode/text/42/9614","subs":["(a)","(b)"],"stext":{"head":"§9614. Relationship to other law","paras":[[0,"(a) Additional State liability or requirements with respect to release of substances within State"],[0,"Nothing in this chapter shall be construed or interpreted as preempting any State from imposing any additional liability or requirements with respect to the release of hazardous substances within such State."],[0,"(b) Recovery under other State or Federal law of compensation for removal costs or damages, or payment of claims"],[0,"Any person who receives compensation for removal costs or damages or claims pursuant to this chapter shall be precluded from recovering compensation for the same removal costs or damages or claims pursuant to any other State or Federal law. Any person who receives compensation for removal costs or damages or claims pursuant to any other Federal or State law shall be precluded from receiving compensation for the same removal costs or damages or claims as provided in this chapter."],[0,"(c) Recycled oil"],[0,"(1) Service station dealers, etc."],[1,"No person (including the United States or any State) may recover, under the authority of subsection (a)(3) or (a)(4) of section 9607 of this title, from a service station dealer for any response costs or damages resulting from a release or threatened release of recycled oil, or use the authority of section 9606 of this title against a service station dealer other than a person described in subsection (a)(1) or (a)(2) of section 9607 of this title, if such recycled oil—"],[2,"(A) is not mixed with any other hazardous substance, and"],[2,"(B) is stored, treated, transported, or otherwise managed in compliance with regulations or standards promulgated pursuant to section 3014 of the Solid Waste Disposal Act [42 U.S.C. 6935] and other applicable authorities."],[1,"Nothing in this paragraph shall affect or modify in any way the obligations or liability of any person under any other provision of State or Federal law, including common law, for damages, injury, or loss resulting from a release or threatened release of any hazardous substance or for removal or remedial action or the costs of removal or remedial action."],[0,"(2) Presumption"],[1,"Solely for the purposes of this subsection, a service station dealer may presume that a small quantity of used oil is not mixed with other hazardous substances if it—"],[2,"(A) has been removed from the engine of a light duty motor vehicle or household appliances by the owner of such vehicle or appliances, and"],[2,"(B) is presented, by such owner, to the dealer for collection, accumulation, and delivery to an oil recycling facility."],[0,"(3) Definition"],[1,"For purposes of this subsection, the terms \"used oil\" and \"recycled oil\" have the same meanings as set forth in sections 1004(36) and 1004(37) of the Solid Waste Disposal Act [42 U.S.C. 6903(36), (37)] and regulations promulgated pursuant to that Act [42 U.S.C. 6901 et seq.]."],[0,"(4) Effective date"],[1,"The effective date of paragraphs (1) and (2) of this subsection shall be the effective date of regulations or standards promulgated under section 3014 of the Solid Waste Disposal Act [42 U.S.C. 6935] that include, among other provisions, a requirement to conduct corrective action to respond to any releases of recycled oil under subtitle C or subtitle I of such Act [42 U.S.C. 6921 et seq., 6991 et seq.]."],[0,"(d) Financial responsibility of owner or operator of vessel or facility under State or local law, rule, or regulation"],[0,"Except as provided in this subchapter, no owner or operator of a vessel or facility who establishes and maintains evidence of financial responsibility in accordance with this subchapter shall be required under any State or local law, rule, or regulation to establish or maintain any other evidence of financial responsibility in connection with liability for the release of a hazardous substance from such vessel or facility. Evidence of compliance with the financial responsibility requirements of this subchapter shall be accepted by a State in lieu of any other requirement of financial responsibility imposed by such State in connection with liability for the release of a hazardous substance from such vessel or facility."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9614?type=usc&year=mostrecent&link-type=html"},"head":"§9614. Relationship to other law","tname":"The Public Health and Welfare","by":{"0":"28","1":"21, 20"}},{"t":"usc","label":"42 U.S.C. § 9615","url":"https://www.law.cornell.edu/uscode/text/42/9615","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 9620","url":"https://www.law.cornell.edu/uscode/text/42/9620","subs":["(d)(2)(B)"],"stext":{"head":"§9620. Federal facilities","paras":[[0,"(a) Application of chapter to Federal Government"],[0,"(1) In general"],[1,"Each department, agency, and instrumentality of the United States (including the executive, legislative, and judicial branches of government) shall be subject to, and comply with, this chapter in the same manner and to the same extent, both procedurally and substantively, as any nongovernmental entity, including liability under section 9607 of this title. Nothing in this section shall be construed to affect the liability of any person or entity under sections 9606 and 9607 of this title."],[0,"(2) Application of requirements to Federal facilities"],[1,"All guidelines, rules, regulations, and criteria which are applicable to preliminary assessments carried out under this chapter for facilities at which hazardous substances are located, applicable to evaluations of such facilities under the National Contingency Plan, applicable to inclusion on the National Priorities List, or applicable to remedial actions at such facilities shall also be applicable to facilities which are owned or operated by a department, agency, or instrumentality of the United States in the same manner and to the extent as such guidelines, rules, regulations, and criteria are applicable to other facilities. No department, agency, or instrumentality of the United States may adopt or utilize any such guidelines, rules, regulations, or criteria which are inconsistent with the guidelines, rules, regulations, and criteria established by the Administrator under this chapter."],[0,"(3) Exceptions"],[1,"This subsection shall not apply to the extent otherwise provided in this section with respect to applicable time periods. This subsection shall also not apply to any requirements relating to bonding, insurance, or financial responsibility. Nothing in this chapter shall be construed to require a State to comply with section 9604(c)(3) of this title in the case of a facility which is owned or operated by any department, agency, or instrumentality of the United States."],[0,"(4) State laws"],[1,"State laws concerning removal and remedial action, including State laws regarding enforcement, shall apply to removal and remedial action at facilities owned or operated by a department, agency, or instrumentality of the United States or facilities that are the subject of a deferral under subsection (h)(3)(C) when such facilities are not included on the National Priorities List. The preceding sentence shall not apply to the extent a State law would apply any standard or requirement to such facilities which is more stringent than the standards and requirements applicable to facilities which are not owned or operated by any such department, agency, or instrumentality."],[0,"(b) Notice"],[0,"Each department, agency, and instrumentality of the United States shall add to the inventory of Federal agency hazardous waste facilities required to be submitted under section 3016 of the Solid Waste Disposal Act [42 U.S.C. 6937] (in addition to the information required under section 3016(a)(3) of such Act [42 U.S.C. 6937(a)(3)]) information on contamination from each facility owned or operated by the department, agency, or instrumentality if such contamination affects contiguous or adjacent property owned by the department, agency, or instrumentality or by any other person, including a description of the monitoring data obtained."],[0,"(c) Federal Agency Hazardous Waste Compliance Docket"],[0,"The Administrator shall establish a special Federal Agency Hazardous Waste Compliance Docket (hereinafter in this section referred to as the \"docket\") which shall contain each of the following:"],[1,"(1) All information submitted under section 3016 of the Solid Waste Disposal Act [42 U.S.C. 6937] and subsection (b) of this section regarding any Federal facility and notice of each subsequent action taken under this chapter with respect to the facility."],[1,"(2) Information submitted by each department, agency, or instrumentality of the United States under section 3005 or 3010 of such Act [42 U.S.C. 6925, 6930]."],[1,"(3) Information submitted by the department, agency, or instrumentality under section 9603 of this title."],[0,"The docket shall be available for public inspection at reasonable times. Six months after establishment of the docket and every 6 months thereafter, the Administrator shall publish in the Federal Register a list of the Federal facilities which have been included in the docket during the immediately preceding 6-month period. Such publication shall also indicate where in the appropriate regional office of the Environmental Protection Agency additional information may be obtained with respect to any facility on the docket. The Administrator shall establish a program to provide information to the public with respect to facilities which are included in the docket under this subsection."],[0,"(d) Assessment and evaluation"],[0,"(1) In general"],[1,"The Administrator shall take steps to assure that a preliminary assessment is conducted for each facility on the docket. Following such preliminary assessment, the Administrator shall, where appropriate—"],[2,"(A) evaluate such facilities in accordance with the criteria established in accordance with section 9605 of this title under the National Contingency Plan for determining priorities among releases; and"],[2,"(B) include such facilities on the National Priorities List maintained under such plan if the facility meets such criteria."],[0,"(2) Application of criteria"],[0,"(A) In general"],[2,"Subject to subparagraph (B), the criteria referred to in paragraph (1) shall be applied in the same manner as the criteria are applied to facilities that are owned or operated by persons other than the United States."],[0,"(B) Response under other law"],[2,"It shall be an appropriate factor to be taken into consideration for the purposes of section 9605(a)(8)(A) of this title that the head of the department, agency, or instrumentality that owns or operates a facility has arranged with the Administrator or appropriate State authorities to respond appropriately, under authority of a law other than this chapter, to a release or threatened release of a hazardous substance."],[0,"(3) Completion"],[1,"Evaluation and listing under this subsection shall be completed in accordance with a reasonable schedule established by the Administrator."],[0,"(e) Required action by department"],[0,"(1) RI/FS"],[1,"Not later than 6 months after the inclusion of any facility on the National Priorities List, the department, agency, or instrumentality which owns or operates such facility shall, in consultation with the Administrator and appropriate State authorities, commence a remedial investigation and feasibility study for such facility. In the case of any facility which is listed on such list before October 17, 1986, the department, agency, or instrumentality which owns or operates such facility shall, in consultation with the Administrator and appropriate State authorities, commence such an investigation and study for such facility within one year after October 17, 1986. The Administrator and appropriate State authorities shall publish a timetable and deadlines for expeditious completion of such investigation and study."],[0,"(2) Commencement of remedial action; interagency agreement"],[1,"The Administrator shall review the results of each investigation and study conducted as provided in paragraph (1). Within 180 days thereafter, the head of the department, agency, or instrumentality concerned shall enter into an interagency agreement with the Administrator for the expeditious completion by such department, agency, or instrumentality of all necessary remedial action at such facility. Substantial continuous physical onsite remedial action shall be commenced at each facility not later than 15 months after completion of the investigation and study. All such interagency agreements, including review of alternative remedial action plans and selection of remedial action, shall comply with the public participation requirements of section 9617 of this title."],[0,"(3) Completion of remedial actions"],[1,"Remedial actions at facilities subject to interagency agreements under this section shall be completed as expeditiously as practicable. Each agency shall include in its annual budget submissions to the Congress a review of alternative agency funding which could be used to provide for the costs of remedial action. The budget submission shall also include a statement of the hazard posed by the facility to human health, welfare, and the environment and identify the specific consequences of failure to begin and complete remedial action."],[0,"(4) Contents of agreement"],[1,"Each interagency agreement under this subsection shall include, but shall not be limited to, each of the following:"],[2,"(A) A review of alternative remedial actions and selection of a remedial action by the head of the relevant department, agency, or instrumentality and the Administrator or, if unable to reach agreement on selection of a remedial action, selection by the Administrator."],[2,"(B) A schedule for the completion of each such remedial action."],[2,"(C) Arrangements for long-term operation and maintenance of the facility."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9620?type=usc&year=mostrecent&link-type=html"},"head":"§9620. Federal facilities","tname":"The Public Health and Welfare","by":{"0":"9","1":"20"}},{"t":"usc","label":"42 U.S.C. § 9622","url":"https://www.law.cornell.edu/uscode/text/42/9622","subs":["(a)","(c)(1)","(d)(1)(B)","(d)(1)(C)","(e)(6)","(g)","(g)(5)","(g)(6)","(g)(12)","(h)(1)","(h)(4)","(f)(6)(A)"],"stext":{"head":"§9622. Settlements","paras":[[0,"(a) Authority to enter into agreements"],[0,"The President, in his discretion, may enter into an agreement with any person (including the owner or operator of the facility from which a release or substantial threat of release emanates, or any other potentially responsible person), to perform any response action (including any action described in section 9604(b) of this title) if the President determines that such action will be done properly by such person. Whenever practicable and in the public interest, as determined by the President, the President shall act to facilitate agreements under this section that are in the public interest and consistent with the National Contingency Plan in order to expedite effective remedial actions and minimize litigation. If the President decides not to use the procedures in this section, the President shall notify in writing potentially responsible parties at the facility of such decision and the reasons why use of the procedures is inappropriate. A decision of the President to use or not to use the procedures in this section is not subject to judicial review."],[0,"(b) Agreements with potentially responsible parties"],[0,"(1) Mixed funding"],[1,"An agreement under this section may provide that the President will reimburse the parties to the agreement from the Fund, with interest, for certain costs of actions under the agreement that the parties have agreed to perform but which the President has agreed to finance. In any case in which the President provides such reimbursement, the President shall make all reasonable efforts to recover the amount of such reimbursement under section 9607 of this title or under other relevant authorities."],[0,"(2) Reviewability"],[1,"The President's decisions regarding the availability of fund financing under this subsection shall not be subject to judicial review under subsection (d)."],[0,"(3) Retention of funds"],[1,"If, as part of any agreement, the President will be carrying out any action and the parties will be paying amounts to the President, the President may, notwithstanding any other provision of law, retain and use such amounts for purposes of carrying out the agreement."],[0,"(4) Future obligation of Fund"],[1,"In the case of a completed remedial action pursuant to an agreement described in paragraph (1), the Fund shall be subject to an obligation for subsequent remedial actions at the same facility but only to the extent that such subsequent actions are necessary by reason of the failure of the original remedial action. Such obligation shall be in a proportion equal to, but not exceeding, the proportion contributed by the Fund for the original remedial action. The Fund's obligation for such future remedial action may be met through Fund expenditures or through payment, following settlement or enforcement action, by parties who were not signatories to the original agreement."],[0,"(c) Effect of agreement"],[0,"(1) Liability"],[1,"Whenever the President has entered into an agreement under this section, the liability to the United States under this chapter of each party to the agreement, including any future liability to the United States, arising from the release or threatened release that is the subject of the agreement shall be limited as provided in the agreement pursuant to a covenant not to sue in accordance with subsection (f). A covenant not to sue may provide that future liability to the United States of a settling potentially responsible party under the agreement may be limited to the same proportion as that established in the original settlement agreement. Nothing in this section shall limit or otherwise affect the authority of any court to review in the consent decree process under subsection (d) any covenant not to sue contained in an agreement under this section. In determining the extent to which the liability of parties to an agreement shall be limited pursuant to a covenant not to sue, the President shall be guided by the principle that a more complete covenant not to sue shall be provided for a more permanent remedy undertaken by such parties."],[0,"(2) Actions against other persons"],[1,"If an agreement has been entered into under this section, the President may take any action under section 9606 of this title against any person who is not a party to the agreement, once the period for submitting a proposal under subsection (e)(2)(B) has expired. Nothing in this section shall be construed to affect either of the following:"],[2,"(A) The liability of any person under section 9606 or 9607 of this title with respect to any costs or damages which are not included in the agreement."],[2,"(B) The authority of the President to maintain an action under this chapter against any person who is not a party to the agreement."],[0,"(d) Enforcement"],[0,"(1) Cleanup agreements"],[0,"(A) Consent decree"],[2,"Whenever the President enters into an agreement under this section with any potentially responsible party with respect to remedial action under section 9606 of this title, following approval of the agreement by the Attorney General, except as otherwise provided in the case of certain administrative settlements referred to in subsection (g), the agreement shall be entered in the appropriate United States district court as a consent decree. The President need not make any finding regarding an imminent and substantial endangerment to the public health or the environment in connection with any such agreement or consent decree."],[0,"(B) Effect"],[2,"The entry of any consent decree under this subsection shall not be construed to be an acknowledgment by the parties that the release or threatened release concerned constitutes an imminent and substantial endangerment to the public health or welfare or the environment. Except as otherwise provided in the Federal Rules of Evidence, the participation by any party in the process under this section shall not be considered an admission of liability for any purpose, and the fact of such participation shall not be admissible in any judicial or administrative proceeding, including a subsequent proceeding under this section."],[0,"(C) Structure"],[2,"The President may fashion a consent decree so that the entering of such decree and compliance with such decree or with any determination or agreement made pursuant to this section shall not be considered an admission of liability for any purpose."],[0,"(2) Public participation"],[0,"(A) Filing of proposed judgment"],[2,"At least 30 days before a final judgment is entered under paragraph (1), the proposed judgment shall be filed with the court."],[0,"(B) Opportunity for comment"],[2,"The Attorney General shall provide an opportunity to persons who are not named as parties to the action to comment on the proposed judgment before its entry by the court as a final judgment. The Attorney General shall consider, and file with the court, any written comments, views, or allegations relating to the proposed judgment. The Attorney General may withdraw or withhold its consent to the proposed judgment if the comments, views, and allegations concerning the judgment disclose facts or considerations which indicate that the proposed judgment is inappropriate, improper, or inadequate."],[0,"(3) 9604(b) agreements"],[1,"Whenever the President enters into an agreement under this section with any potentially responsible party with respect to action under section 9604(b) of this title, the President shall issue an order or enter into a decree setting forth the obligations of such party. The United States district court for the district in which the release or threatened release occurs may enforce such order or decree."],[0,"(e) Special notice procedures"],[0,"(1) Notice"],[1,"Whenever the President determines that a period of negotiation under this subsection would facilitate an agreement with potentially responsible parties for taking response action (including any action described in section 9604(b) of this title) and would expedite remedial action, the President shall so notify all such parties and shall provide them with information concerning each of the following:"],[2,"(A) The names and addresses of potentially responsible parties (including owners and operators and other persons referred to in section 9607(a) of this title), to the extent such information is available."],[2,"(B) To the extent such information is available, the volume and nature of substances contributed by each potentially responsible party identified at the facility."],[2,"(C) A ranking by volume of the substances at the facility, to the extent such information is available."],[1,"The President shall make the information referred to in this paragraph available in advance of notice under this paragraph upon the request of a potentially responsible party in accordance with procedures provided by the President. The provisions of subsection (e) of section 9604 of this title regarding protection of confidential information apply to information provided under this paragraph. Disclosure of information generated by the President under this section to persons other than the Congress, or any duly authorized Committee thereof, is subject to other privileges or protections provided by law, including (but not limited to) those applicable to attorney work product. Nothing contained in this paragraph or in other provisions of this chapter shall be construed, interpreted, or applied to diminish the required disclosure of information under other provisions of this or other Federal or State laws."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9622?type=usc&year=mostrecent&link-type=html"},"head":"§9622. Settlements","tname":"The Public Health and Welfare","by":{"0":"3, 40, 39","1":"20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 4, 4, 4, 4, 4","2":"15, 20"}},{"t":"usc","label":"42 U.S.C. § 9652","url":"https://www.law.cornell.edu/uscode/text/42/9652","subs":["(d)"],"stext":{"head":"§9652. Effective dates; savings provisions","paras":[[0,"(a) Unless otherwise provided, all provisions of this chapter shall be effective on December 11, 1980."],[0,"(b) Any regulation issued pursuant to any provisions of section 1321 of title 33 which is repealed or superseded by this chapter and which is in effect on the date immediately preceding the effective date of this chapter shall be deemed to be a regulation issued pursuant to the authority of this chapter and shall remain in full force and effect unless or until superseded by new regulations issued thereunder."],[0,"(c) Any regulation—"],[1,"(1) respecting financial responsibility,"],[1,"(2) issued pursuant to any provision of law repealed or superseded by this chapter, and"],[1,"(3) in effect on the date immediately preceding the effective date of this chapter shall be deemed to be a regulation issued pursuant to the authority of this chapter and shall remain in full force and effect unless or until superseded by new regulations issued thereunder."],[0,"(d) Nothing in this chapter shall affect or modify in any way the obligations or liabilities of any person under other Federal or State law, including common law, with respect to releases of hazardous substances or other pollutants or contaminants. The provisions of this chapter shall not be considered, interpreted, or construed in any way as reflecting a determination, in part or whole, of policy regarding the inapplicability of strict liability, or strict liability doctrines, to activities relating to hazardous substances, pollutants, or contaminants or other such activities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9652?type=usc&year=mostrecent&link-type=html"},"head":"§9652. Effective dates; savings provisions","tname":"The Public Health and Welfare","by":{"0":"26, 28","1":"4","2":"12"}},{"t":"usc","label":"48 U.S.C. § 1421a","url":"https://www.law.cornell.edu/uscode/text/48/1421a","by":{"0":"7"}},{"t":"law","label":"Pub. L. No. 99-499","url":"https://www.govinfo.gov/link/statute/100/1613","by":{"0":"5","1":"3"}},{"t":"reg","label":"40 C.F.R. § 302.4","url":"https://www.ecfr.gov/current/title-40/section-302.4","by":{"0":"37"}},{"t":"case","label":"Alexander v. Gardner-Denver Co.","cite":"415 U.S. 36","y":1974,"id":"1973/72-5847","sc":1,"sum":"An employee's statutory right to trial de novo under Title VII of the Civil Rights Act of 1964 is not foreclosed by prior submission of his claim to final arbitration under the nondiscrimination clause of a collective-bargaining.agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Chamberlain v. Carborundum Co.","cite":"485 F.2d 31","y":1973,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/485/31/","by":{"1":"29"}},{"t":"case","label":"Credit Suisse Securities (USA) LLC v. Billing","cite":"551 U.S. 264","y":2007,"id":"2006/05-1157","sc":1,"op":3,"sum":"The Court reversed the Second Circuit and ruled that the applicable securities laws granted the defendant implied antitrust immunity. The 7-1 ruling by Justice Stephen G. Breyer noted four factors indicating that the Securities Act of 1933 foreclosed antitrust lawsuits in cases of alleged artificial inflation of aftermarket IPO share prices.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Department of Homeland Security v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"1":"19","2":"8"}},{"t":"case","label":"Farmers Insurance Exchange v. Village of Hewitt","cite":"143 N.W.2d 230","y":1966,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/143/230/","by":{"1":"29"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Florida Power Corp. v. FirstEnergy Corp.","cite":"810 F.3d 996","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/810/996/","by":{"1":"42"}},{"t":"case","label":"Guillard v. Niagara Machine & Tool Works","cite":"488 F.2d 20","y":1973,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/488/20/","by":{"1":"29"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"op":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"1":"17, 19, 25, 26, 27","2":"3"}},{"t":"case","label":"Kansas v. Garcia","cite":"140 S. Ct. 791","y":2020,"id":"2019/17-834","sc":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Lomax v. Ortiz-Marquez","cite":"140 S. Ct. 1721","y":2020,"id":"2019/18-8369","sc":1,"sum":"The Court held that a dismissal without prejudice for failure to state a claim counts as a strike under the Prison Litigation Reform Act, 28 U.S.C. § 1915(g), which bars inmates from filing or appealing a federal civil action without paying the associated fees if they have filed three or more cases or appeals that were dismissed because the lawsuits were frivolous or malicious or did not properly state a legal claim for relief.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"1":"26","2":"3"}},{"t":"case","label":"Maher v. Gagne","cite":"448 U.S. 122","y":1980,"id":"1979/78-1888","sc":1,"sum":"Respondent is a recipient of benefits under Connecticut's federally funded Aid to Families with Dependent Children (AFDC) program. She brought this action in Federal District Court under 42 U. S. C. § 1983, alleging that Connecticut's AFDC regulations denied her credit for substantial portions of her actual work-related expenses, thus reducing the level of her benefits, and that'such regulations violated the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Peter v. NantKwest, Inc.","cite":"140 S. Ct. 365","y":2019,"id":"2019/18-801","sc":1,"op":1,"sum":"The Court held that the phrase “[a]ll the expenses of the proceedings” in 35 U.S.C. § 145 does not include attorneys’ fees incurred as a result of defending the agency in § 145 litigation.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"PLIVA, Inc. v. Mensing","cite":"564 U.S. 604","y":2011,"id":"2010/09-993","sc":1,"sum":"The Court held that generic drug makers cannot be sued for not warning about potentially dangerous side effects on their drug labels, even when they follow federal rules that only require their labels to match those of their brand-name equivalents.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"RSR Corp. v. Commercial Metals Co.","cite":"496 F.3d 552","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/496/552/","by":{"1":"46"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"case","label":"Refined Metals Corp. v. NL Industries Inc.","cite":"937 F.3d 928","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/937/928/","by":{"1":"23, 46"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"19"}},{"t":"case","label":"Roberts v. Sea-Land Services, Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Shaw v. Railroad Co.","cite":"101 U.S. 557","y":1880,"id":"scdb/1879-108","sc":1,"sum":"This is an action of replevin brought by the Merchants’ National Bankof St. Louis, Missouri, against Shaw & Esrey, of Philadelphia, Pennsylvania, to recover possession of certain cotton, marked “ W D I.” One hundred and forty-one bales thereof having been taken possession of by the marshal were returned to the defendants upon their entering into the proper bond. On Nov. 11, 1874, Norvell & Co., of St. Louis, sold to …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Southern Railway Co. v. Foote Mineral Co.","cite":"384 F.2d 224","y":1967,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/384/224/","by":{"1":"29"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Texas Industries, Inc. v. Radcliff Materials, Inc.","cite":"451 U.S. 630","y":1981,"id":"1980/79-1144","sc":1,"op":1,"sum":"Noting a “narrow exception” for admiralty cases.","sumSrc":"opinion","by":{"1":"3","2":"9"}},{"t":"case","label":"Trinity Industries, Inc. v. Chicago Bridge & Iron Co.","cite":"735 F.3d 131","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/735/131/","by":{"1":"23, 33"}},{"t":"case","label":"United States v. Colorado","cite":"990 F.2d 1565","y":1993,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/990/1565/","by":{"1":"21"}},{"t":"case","label":"United States National Bank v. Independent Insurance Agents of America, Inc.","cite":"508 U.S. 439","y":1993,"id":"1992/92-484","sc":1,"sum":"The Act of Sept. 7, 1916, 39 Stat. 753 (1916 Act), among other things, authorized any national bank doing business in a community with a population not exceeding 5,000 to act as the agent for any insurance company. Although early editions of the United States Code included this provision as section 92 of Title 12 (section 92), the 1952 Code and subsequent editions omitted section 92 with a note indicating that …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"W.R. Grace & Co.—Connecticut v. Zotos Int’l, Inc.","cite":"559 F.3d 85","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/559/85/","by":{"1":"24"}},{"t":"case","label":"Wood v. Allen","cite":"558 U.S. 290","y":2010,"id":"2009/08-9156","sc":1,"sum":"The Court held that an inmate's conviction was proper, despite the fact that his attorney failed to properly investigate or introduce evidence that his IQ was well below average.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Case—Continued: Zontelli Bros. v. Northern Pacific Railway Co.","cite":"263 F.2d 194","y":1959,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/263/194/","ar":1,"by":{"1":"29"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"1":"32"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"1":"6, 14"}},{"t":"usc","label":"42 U.S.C. § 9612","url":"https://www.law.cornell.edu/uscode/text/42/9612","subs":["(c)(2)"],"by":{"1":"43"}},{"t":"usc","label":"42 U.S.C. § 9619","url":"https://www.law.cornell.edu/uscode/text/42/9619","subs":["(e)(1)"],"by":{"1":"20"}},{"t":"usc","label":"42 U.S.C. § 9656","url":"https://www.law.cornell.edu/uscode/text/42/9656","subs":["(b)"],"by":{"1":"4"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(b)(2)(E)"],"by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/18/1344","subs":["(2)"],"by":{"1":"26"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"by":{"1":"9"}},{"t":"case","label":"BFP v. Resolution Trust Corp.","cite":"511 U.S. 531","y":1994,"id":"1993/92-1370","sc":1,"sum":"The Court ruled 5-4 that the value received for a property at a foreclosure sale can be reasonable even if it is different from the \"fair market value.\" A foreclosure sale alters market conditions and can lower a property's selling price.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Cranbury Brick Yard, LLC v. United States","cite":"943 F.3d 701","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/943/701/","by":{"2":"8"}},{"t":"case","label":"Facebook, Inc. v. Duguid","cite":"141 S. Ct. 1163","y":2021,"id":"2020/18-956","sc":1,"sum":"Google’s limited copying of the Java SE Application Programming Interface allowed programmers to put their accrued talents to work in a transformative program and constituted a fair use of that material under copyright law.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"21"}},{"t":"case","label":"FCC v. NextWave Personal Communications, Inc.","cite":"537 U.S. 293","y":2003,"id":"2002/01-653","sc":1,"sum":"The Court held that the FCC's cancellations of the licenses violated section 525(a) as revocations of government licenses solely for nonpayment of the debtors' dischargeable debts.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Fourth Estate Public Benefit Corp. v. WallStreet.com, LLC","cite":"139 S. Ct. 881","y":2019,"id":"2018/17-571","sc":1,"sum":"Registration occurs, and a copyright claimant may commence an infringement suit, when the Copyright Office registers a copyright.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"5"}},{"t":"case","label":"Graham County Soil & Water Conservation District v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"2"}},{"t":"case","label":"Intel Corp. Investment Policy Committee v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Lexmark International, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"United States v. Atlantic Refining Co.","cite":"360 U.S. 19","y":1959,"id":"1958/210","sc":1,"sum":"The judgment is affirmed. Pp. 20-24. Affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"usc","label":"33 U.S.C. § 2709","url":"https://www.law.cornell.edu/uscode/text/33/2709","by":{"2":"11"}},{"t":"usc","label":"42 U.S.C. § 9659","url":"https://www.law.cornell.edu/uscode/text/42/9659","subs":["(h)"],"by":{"2":"12"}}]};